  const quad=(a,b,c,d,fl)=>{if(a<0||b<0||c<0||d<0)return;if(fl){const t=b;b=d;d=t;}
    const dx=(q,r)=>{const o=q*3,p=r*3;return(pos[o]-pos[p])**2+(pos[o+1]-pos[p+1])**2+(pos[o+2]-pos[p+2])**2;};
    if(dx(a,c)<=dx(b,d))idx.push(a,b,c,a,c,d);else idx.push(a,b,d,b,c,d);};
