/* układ siatki (x,y,z; z do góry) -> układ strony (y do góry, przód +z) */
function toPage(m){const p=m.p;for(let k=0;k<p.length;k+=3){const y=p[k+1],z=p[k+2];p[k+1]=z;p[k+2]=-y;}return orient(m);}
