  for(let y=0;y<H;y++)for(let x=0;x<W;x++){const e=(x===0||y===0||x===W-1||y===H-1);f[y*W+x]=e?(padv?INF:0):(m[(y-1)*w+x-1]?INF:0);}
  const n=Math.max(W,H),v=new Int32Array(n),z=new Float64Array(n+1),g=new Float64Array(n),o=new Float64Array(n);
  for(let x=0;x<W;x++){for(let y=0;y<H;y++)g[y]=f[y*W+x];dt1(g,H,o,v,z);for(let y=0;y<H;y++)f[y*W+x]=o[y];}
  for(let y=0;y<H;y++){for(let x=0;x<W;x++)g[x]=f[y*W+x];dt1(g,W,o,v,z);for(let x=0;x<W;x++)f[y*W+x]=o[x];}
