function catmullClosed(pts,n){
  const N=pts.length,out=[];
  for(let i=0;i<N;i++){const p0=pts[(i-1+N)%N],p1=pts[i],p2=pts[(i+1)%N],p3=pts[(i+2)%N];
    for(let s=0;s<n;s++){const t=s/n,t2=t*t,t3=t2*t;
      out.push([0,1].map(d=>0.5*((2*p1[d])+(-p0[d]+p2[d])*t+(2*p0[d]-5*p1[d]+4*p2[d]-p3[d])*t2+(-p0[d]+3*p1[d]-3*p2[d]+p3[d])*t3)));}}
  return out;
}
const linsp=(a,b,n)=>{const o=[];for(let i=0;i<n;i++)o.push(a+(b-a)*i/(n-1));return o;};

/* ===== uchwyty linii: czop 5x5x8, gniazdo 5,4x5,4x9, ramka montażowa ===== */
const PEG_W=LINE.const.PEG_W,PEG_L=LINE.const.PEG_L,PEG_R=LINE.const.PEG_R,SOCK_W=LINE.const.SOCK_W,SOCK_D=LINE.const.SOCK_D,SOCK_R=LINE.const.SOCK_R,Y0=LINE.const.EAR_Y,GAP=LINE.const.GAP;
function rboxF(a,b,c,lo,hi,rad){
  const q0=Math.abs(a-(lo[0]+hi[0])/2)-((hi[0]-lo[0])/2-rad),q1=Math.abs(b-(lo[1]+hi[1])/2)-((hi[1]-lo[1])/2-rad),q2=Math.abs(c-(lo[2]+hi[2])/2)-((hi[2]-lo[2])/2-rad);
  const m0=Math.max(q0,0),m1=Math.max(q1,0),m2=Math.max(q2,0),out=Math.sqrt(m0*m0+m1*m1+m2*m2),ins=Math.min(Math.max(q0,q1,q2),0);
  return-(out+ins-rad);
}
const socketF=(a,b,c)=>rboxF(a,b,c,[-SOCK_W/2,-SOCK_D,2.5-SOCK_W/2],[SOCK_W/2,1.5,2.5+SOCK_W/2],SOCK_R);
const pegExtF=(a,b,c)=>rboxF(a,b,c,[-PEG_W/2,-PEG_L,0],[PEG_W/2,2,PEG_W],PEG_R);
function mountFrame(side,P0,tilt){
  const s=Math.sin(tilt),c=Math.cos(tilt),B=[side*s,0,c],C=[0,-1,0];
  const A=[B[1]*C[2]-B[2]*C[1],B[2]*C[0]-B[0]*C[2],B[0]*C[1]-B[1]*C[0]];
  return mkFrame([P0[0]-2.5*C[0],P0[1]-2.5*C[1],P0[2]-2.5*C[2]],A,B,C);
}
const frameXf=(fr,m)=>xf(m,(a,b,c)=>[fr.O[0]+a*fr.A[0]+b*fr.B[0]+c*fr.C[0],fr.O[1]+a*fr.A[1]+b*fr.B[1]+c*fr.C[1],fr.O[2]+a*fr.A[2]+b*fr.B[2]+c*fr.C[2]]);
function partFn(fp,plateB0,trims,peg,cmax){
  return(a,b,c)=>{
    if(c<-0.7||c>cmax)return-9;
    let f=Math.min(fp.F(a,b,c),b-plateB0);
    if(trims){const X=trims.fr;const x=X.O[0]+a*X.A[0]+b*X.B[0]+c*X.C[0],y=X.O[1]+a*X.A[1]+b*X.B[1]+c*X.C[1],z=X.O[2]+a*X.A[2]+b*X.B[2]+c*X.C[2];
      for(const t of trims.sdf)f=Math.min(f,-(t(x,y,z)+GAP));}
    if(peg)f=Math.max(f,pegExtF(a,b,c));
    return f;
  };
}

/* ===== kształty z linii (porty skryptów Pythona) ===== */
const nRibs=r=>Math.round(2*Math.PI*r/LINE.const.RIB_PITCH);
const IDM={O:[0,0,0],A:[1,0,0],B:[0,1,0],C:[0,0,1]};
function bunDef(P){
  const B={R:P.bodyW/2,HZ:P.bodyHz,N:P.bodyN,HR:P.headR,HC:P.headZ,SP:P.blend,amp:P.ribDepth/2,pw:P.ribPow,n:Math.round(P.ribs)};
  B.ZC=0.8*B.HZ;
  B.prof=z=>{
    const u=(z-B.ZC)/B.HZ,ub=Math.min(Math.abs(u),1);
    const rb=Math.abs(u)<=1?B.R*Math.pow(Math.max(1-Math.pow(ub,B.N),0),1/B.N):0;
    const v=clamp((z-B.HC)/B.HR,-1,1),rh=B.HR*Math.sqrt(Math.max(1-v*v,0));
    return Math.pow(Math.pow(rb,B.SP)+Math.pow(rh,B.SP),1/B.SP);
  };
  const r0=Math.hypot(P.earX,Y0);
  B.P0=side=>[side*P.earX,Y0,B.HC+Math.sqrt(Math.max(B.HR*B.HR-r0*r0,0))];
  B.sdf=(x,y,z)=>B.HR+0.3-Math.sqrt(x*x+y*y+(z-B.HC)*(z-B.HC));
  B.top=B.HC+B.HR;
  return B;
}
function fillBun(G,B){latheField(G,{R:B.prof,N:B.n,amp:B.amp,pow:B.pw});planeZ(G,0,1e9);}
const polyLR=(L,R,bs)=>bs.map(b=>[R(b),b]).concat(bs.slice().reverse().map(b=>[L(b),b]));

/* specyfikacje płaskich dodatków: mk(mirror)->FlatPart, L, ar(side)->zakres a */
function earSpec(kind,P,res0){
  const T=P.earT,res=res0||0.1;
  if(kind==='rab'){
    const L=P.earL,hm=P.earW/2,hb=4.2*hm/7,A=hm+2,k=hm/7;
    const hw=b=>{const u=b/L;if(u<0.5)return hb+(hm-hb)*Math.sin(Math.PI/2*Math.max(u,0)/0.5);const t=(u-0.5)/0.5;return hm*Math.pow(Math.max(1-Math.pow(t,2.2),0),1/2.2);};
    const bs=linsp(-3,L,200);
    return{L,T,ar:()=>[-A,A],mk:()=>{const cv=new Canvas(-A,A,-4.5,L+2,res);cv.poly(polyLR(b=>-hw(b),hw,bs));
      const ring=new Canvas(-A,A,-4.5,L+2,res);ring.ellipse(0,0.55*L,3.5*k,0.34*L,1);ring.ellipse(0,0.55*L,2.6*k,Math.max(0.34*L-0.9,0.1),0);
      return new FlatPart(cv,T,{w:1,k:1.5,ring:ring.m,ringH:P.ringH});}};
  }
  if(kind==='tri'){
    const L=P.earL,hw0=P.earW/2,lean=P.earLean,q=P.earQ,openR=P.earOpen,ringIn=P.ringIn,ringTop=P.ringTop;
    const cen=b=>lean*Math.pow(Math.max(b,0)/L,1.6),hw=b=>hw0*Math.pow(Math.max(1-Math.max(b,0)/L,0),q);
    return{L,T,ar:s=>s>0?[-10,15]:[-15,10],mk:mirror=>{
      const cv=new Canvas(-10,15,-4.5,L+2,res);cv.poly(polyLR(b=>cen(b)-hw(b),b=>cen(b)+hw(b),linsp(-3,L,300)));cv.openR(openR);
      const ring=new Canvas(-10,15,-4.5,L+2,res),bs=linsp(3.2,L*ringTop,120),inn=(b,o)=>Math.max(hw(b)-o,0);
      ring.poly(polyLR(b=>cen(b)-inn(b,ringIn),b=>cen(b)+inn(b,ringIn),bs),1);
      ring.poly(polyLR(b=>cen(b)-inn(b,ringIn+0.9),b=>cen(b)+inn(b,ringIn+0.9),bs),0);
      return new FlatPart(cv,T,{w:1,k:1.5,ring:ring.m,ringH:P.ringH,mirror});}};
  }
  if(kind==='round'){
    const r=P.earR,bc=P.earBc,neck=4.2,L=bc+r;
    return{L,T,ar:s=>s>0?[-10,15]:[-15,10],mk:mirror=>{
      const cv=new Canvas(-10,15,-4.5,L+6,res);cv.ellipse(0,bc,r,r,1);cv.rect(-neck,neck,-3,bc-1,1);cv.closeR(2.2);cv.openR(1.0);
      return new FlatPart(cv,T,{w:1,k:0.9,mirror});}};
  }
  if(kind==='tuft'){
    const L=P.earL,hmax=P.earW/2,lean=P.earLean;
    const cen=b=>lean*Math.pow(Math.max(b,0)/L,1.7);
    const hw=b=>{const u=Math.max(b,0)/L;if(u<0.45)return 4.2+(hmax-4.2)*Math.sin(Math.PI/2*u/0.45);const t=(u-0.45)/0.55;return hmax*Math.pow(Math.max(1-Math.pow(t,1.9),0),1/1.9);};
    return{L,T,ar:s=>s>0?[-10,15]:[-15,10],mk:mirror=>{
      const cv=new Canvas(-10,15,-4.5,L+2,res);cv.poly(polyLR(b=>cen(b)-hw(b),b=>cen(b)+hw(b),linsp(-3,L,300)));cv.openR(0.9);
      const gr=new Canvas(-10,15,-4.5,L+2,res);
      for(const off of[-1.5,1.5])gr.path(linsp(4.5,0.82*L,40).map(b=>[cen(b)+off*(1-0.35*b/L),b]),0.9);
      return new FlatPart(cv,T,{w:1,k:1.5,groove:gr.m,grooveD:0.7,mirror});}};
  }
  if(kind==='ant'){
    const s=P.antS,wm=P.antW,A0=-8*s-2,A1=20*s+2,Lc=36*s;
    const sc=p=>[p[0]*s,p[1]*s];
    return{L:Lc,T,ar:sd=>sd>0?[-10,Math.max(21,22*s)]:[-Math.max(21,22*s),10],mk:mirror=>{
      const cv=new Canvas(A0,A1,-4.5,Lc+2,res);
      cv.path([[0,-3],[0.3,4],[0.4,12],[0,20],[-0.8,26.5],[-1.2,28.6]].map(sc),4.2*wm,1);
      cv.rect(-3.4*s,3.4*s,-3*s,4*s,1);
      cv.path([[0.5,5],[4.5,10.1],[8.5,15.2]].map(sc),3.7*wm,1);
      cv.path([[0.3,18],[4.3,23.1],[8.3,28.2]].map(sc),3.7*wm,1);
      cv.closeR(2.0);cv.openR(1.2);
      return new FlatPart(cv,T,{w:1,k:2.2,mirror});}};
  }
  return null;
}
/* uszy: przytopione (fuse) albo osobne z czopem (detach) */
function fuseEars(G,B,spec,P,frameFn){
  const mk0=spec.mk(false),mk1=spec.mk(true);
  for(const side of[1,-1]){
    const fr=frameFn(side),fp=side>0?mk0:mk1;
    localField(G,fr,partFn(fp,-4.5,null,false,spec.T+1.5),spec.ar(side),[-9,spec.L+3],[-1,8],'max');
  }
}
function cutSockets(G,frameFn){
  for(const side of[1,-1])localField(G,frameFn(side),socketF,[-5,5],[-9,2],[-1,6],'cut');
}
function earPart(spec,side,frameFn,sdfs,vox){
  const fr=frameFn(side),fp=spec.mk(side<0),ar=spec.ar(side),br=[-9,spec.L+3],cr=[-0.6,spec.T+1.7];
  const v=clamp(vox*0.6,0.22,0.45),G=mkGrid(ar[0],ar[1],br[0],br[1],cr[0],cr[1],v);
  localField(G,IDM,partFn(fp,-3.0,{fr,sdf:sdfs},true,spec.T+1.5),ar,br,cr,'max');
  return{fr,m:surfaceNets(G)};
}
function addEarParts(parts,spec,frameFn,sdfs,vox,explode,name){
  for(const side of[1,-1]){
    const e=earPart(spec,side,frameFn,sdfs,vox),ex=toPage({p:e.m.p.slice(),i:e.m.i.slice()});
    const g=frameXf(e.fr,{p:e.m.p,i:e.m.i});toPage(g);
    if(explode){const B=e.fr.B,k=explode*0.5;translate(g,B[0]*k,B[2]*k,-B[1]*k);}
    parts.push({name:name+(side>0?' P':' L'),m:g,ex,g:'ucho_'+(side>0?'prawe':'lewe')});
  }
}

/* ---- narzędzia pól analitycznych ---- */
function tailF(P,rib){
  const al=P.tailA*D2R,d=[0,Math.sin(al),Math.cos(al)],e2=[0,d[2],-d[1]],Lt=P.tailL,Rm=P.tailR,N=P.tailN,amp=P.ribDepth/2,pt=[0,12,14];
  return(x,y,z)=>{
    const rx=x-pt[0],ry=y-pt[1],rz=z-pt[2],s=ry*d[1]+rz*d[2];
    if(s<-4||s>Lt+1)return-1;
    const u2=ry*e2[1]+rz*e2[2],rho=Math.sqrt(rx*rx+u2*u2);
    if(rho>Rm+1.5)return-1;
    const th=Math.atan2(u2,rx),u=s<0?0:s>Lt?1:s/Lt,R=Rm*Math.pow(Math.max(4*u*(1-u),0),0.72),a=amp*(R<1.2?0:R>4?1:(R-1.2)/2.8);
    const F=(R+a*sgnPow(Math.cos(N*th),rib)-1e-3)-rho;
    return Math.min(F,Math.min(s+3,Lt-s));
  };
}
function eyeCapF(B,P,sx){
  const dz=2.2,ax=P.eyeX,RH=B.HR,thE=P.eyeS,thP=thE*0.46,top=RH+1.9,topP=RH+3.1;
  let e=[sx*ax,-Math.sqrt(Math.max(RH*RH-ax*ax-dz*dz,0.01)),dz];const el=Math.sqrt(e[0]*e[0]+e[1]*e[1]+e[2]*e[2]);e=e.map(v=>v/el);
  return(x,y,z)=>{
    const rx=x,ry=y,rz=z-B.HC,r=Math.sqrt(rx*rx+ry*ry+rz*rz)+1e-6,ang=Math.acos(clamp((rx*e[0]+ry*e[1]+rz*e[2])/r,-1,1));
    return Math.max(Math.min((thE-ang)*RH,top-r),Math.min((thP-ang)*RH,topP-r));
  };
}
function beakF(zc,sSurf,length,hw,hh,back){
  return(x,y,z)=>{
    const s=-y,t=(sSurf+length-s)/length,q=Math.sqrt((x/hw)*(x/hw)+((z-zc)/hh)*((z-zc)/hh));
    return Math.min((t-q)*Math.min(hw,hh),Math.min(sSurf+length-s,s-(sSurf-back)));
  };
}
function haloF(P){
  const zc=P.haloZ,ro=P.haloRo,ri=P.haloRi,T=P.haloT,zs=P.haloZ-22,sw=2.3;
  return(x,y,z)=>{
    const rho2=Math.sqrt(x*x+(z-zc)*(z-zc)),ring=Math.min(ro-rho2,rho2-ri,T/2-Math.abs(y));
    const stem=Math.min(sw-Math.abs(x),z-zs,(zc-ro+2.5)-z,T/2-Math.abs(y));
    return Math.max(ring,stem);
  };
}
/* skrzydło-wachlarz odczytane z modelu anioła: obrys (a,b) oraz 6 rowków */
const WING_PTS=[[14,71],[19.5,70.4],[25.1,73.2],[38.9,84.2],[44.3,88.6],[47.2,91.7],[49.4,95.3],[49.6,96.1],[49.4,97.1],[47.5,97.8],[46.6,98.7],[47.6,100.7],[47.8,102.3],[47.8,103.1],[46.9,104],[45.7,104],[44.5,103.4],[43.6,104.3],[44,105.5],[44,106.7],[44.2,108.1],[43.3,109],[42.3,109],[41.3,108.6],[40.1,107.6],[39.7,107.6],[38.8,108.5],[38.8,110.7],[37.7,111.8],[36.1,111.4],[33.7,109.2],[32.6,110.1],[32.2,111.3],[31.7,111.8],[29.9,111.6],[26.7,108.2],[25.1,109.6],[24.3,109.6],[22.6,108.1],[21.8,106.7],[20.3,104.6],[17,104],[14,100]];
const WING_GR=[[[33.9,85.3],[45.1,94.1]],[[32.1,87.7],[43.7,99.7]],[[30.2,90.3],[40.3,104.1]],[[28.1,93.1],[35.4,106.8]],[[25.9,96.6],[29.6,106.9]],[[23,100.4],[23.9,104.9]]];
function wingFlat(P,res){
  const s=P.wingS,o=[19,71],sc=p=>[o[0]+(p[0]-o[0])*s,o[1]+(p[1]-o[1])*s];
  const pts=WING_PTS.map(sc);let a0=1e9,a1=-1e9,b0=1e9,b1=-1e9;
  for(const p of pts){a0=Math.min(a0,p[0]);a1=Math.max(a1,p[0]);b0=Math.min(b0,p[1]);b1=Math.max(b1,p[1]);}
  a0-=3;a1+=3;b0-=3;b1+=3;
  const cv=new Canvas(a0,a1,b0,b1,res);cv.poly(pts);cv.openR(0.5);
  const gr=new Canvas(a0,a1,b0,b1,res);
  for(const g of WING_GR)gr.line(sc(g[0]),sc(g[1]),1.0,1);
  return{fp:new FlatPart(cv,P.wingT,{w:1,k:1.5,groove:gr.m,grooveD:0.8}),a:[a0,a1],b:[b0,b1]};
}
function wingFrame(P,s){
  const ph=P.wingA*D2R,A=[s*Math.cos(ph),Math.sin(ph),0],Bv=[0,0,1],C=[s*Math.sin(ph),-Math.cos(ph),0],k=P.wingC-P.wingT/2;
  return mkFrame([C[0]*k,C[1]*k,P.wingZ+C[2]*k],A,Bv,C);
}

/* ---- czapki (krasnal / Mikołaj) ---- */
const coneR=(z,z0,z1,r0,r1,p)=>{if(z<z0||z>z1)return 0;const t=clamp((z-z0)/(z1-z0),0,1);return r1+(r0-r1)*Math.pow(1-t,p);};
function cuffR(z,z0,h,Rc,rf){rf=rf||1.6;const zz=z-z0;if(zz<0||zz>h)return 0;
  const lo=Math.sqrt(Math.max(rf*rf-(rf-zz)*(rf-zz),0)),hi=Math.sqrt(Math.max(rf*rf-(rf-(h-zz))*(rf-(h-zz)),0));
  return Rc-rf+(zz<rf?lo:zz>h-rf?hi:rf);}
const ballR=(z,zc,R)=>Math.sqrt(Math.max(R*R-(z-zc)*(z-zc),0));
function mkHat(kind,zb,ztop,Rb,N,chamfer,p,P){
  const h={kind,zb,ztop,Rb,N,ch:chamfer,p,zlo:zb-chamfer};
  if(kind==='mikolaj'){
    h.cuffH=P.cuffH;h.Rc=Rb+1;h.Rpom=P.pomR;h.zpom=ztop-h.Rpom;h.zc0=zb+h.cuffH-1;h.zc1=h.zpom+1;h.rb=Rb-1;h.rt=3.2;
    h.rib0=zb+h.cuffH+0.5;h.rib1=zb+h.cuffH+3;h.rib2=h.zpom-4;h.rib3=h.zpom-1.5;
  }else{h.rt=1.6;h.rib0=zb+4+chamfer;h.rib1=zb+7+chamfer;}
  h.R=z=>{
    let r=kind==='mikolaj'?Math.max(cuffR(z,zb,h.cuffH,h.Rc),Math.max(coneR(z,h.zc0,h.zc1,h.rb,h.rt,1.15),ballR(z,h.zpom,h.Rpom))):coneR(z,zb,ztop,Rb,h.rt,p);
    if(chamfer>0&&z>=zb-chamfer&&z<zb)r=Math.max(r,Rb-(zb-z));
    return r;
  };
  h.w=z=>kind==='mikolaj'?sstep(z,h.rib0,h.rib1)*(1-sstep(z,h.rib2,h.rib3)):sstep(z,h.rib0,h.rib1);
  return h;
}
function hatField(G,h,amp,pw,mode){latheField(G,{R:h.R,N:h.N,amp,pow:pw,w:h.w,mode,zlo:h.zlo,zhi:h.ztop});}

/* ---- jajko ---- */
function eggDef(P){
  const SL=LINE.const.LP_SLOPE;   /* największe nachylenie obrysu dobudowanego do wnętrza (dr/dz): jak sufity wnęk (STANDARD LP_SLOPE = 1,3), bez nawisów ostrzejszych niż 52° */
  const E={H:P.eggH,ZM:P.eggZ,Rcav:P.cavR,floor:P.floor,lipH:P.lipH,wallCup:P.wallCup,lipWall:1.2,clR:0.25,clZ:0.2,wcap:2.6,ceil:P.ceilZ,Rtop:LINE.models.jajko.cone.R_TOP,
    n:Math.round(P.ribs),amp:P.ribDepth/2,pw:P.ribPow};
  E.ZS=P.seam;E.Z0=E.ZS+E.clZ;E.Rlip=E.Rcav+E.lipWall;E.Rbore=E.Rlip+E.clR;E.ZL=E.ZS+E.lipH;
  E.cone=LINE.models.jajko.cone.slope;E.ZA=E.ceil-(E.Rcav-E.Rtop)/E.cone;
  const sup=(RM,ZM,H,NL,NU)=>z=>{
    if(z<=ZM){const ul=clamp((ZM-z)/(ZM/0.9),0,1);return RM*Math.pow(Math.max(1-Math.pow(ul,NL),0),1/NL);}
    const uu=clamp((z-ZM)/(H-ZM),0,1);return RM*Math.pow(Math.max(1-Math.pow(uu,NU),0),1/NU);};
  /* WNĘTRZE I SZEW: wyliczane z powłoki odniesienia (EGG_REF, szew, wnęka, dno, sufit), NIE z obrysu zewnętrznego.
     Dzięki temu jajko niespodzianka i połączenie miseczka/czapka pasują tak samo przy każdym kształcie zewnętrznym. */
  E.Rref=sup(EGG_REF.W/2,E.ZS,EGG_REF.H,EGG_REF.NL,EGG_REF.NU);
  E.cupCav=z=>(z>=E.floor&&z<=E.ZS+E.lipH+0.01)?Math.min(E.Rref(z)-E.wallCup,E.Rcav):-1;
  const capBody=z=>Math.min(Math.min(E.Rcav,E.Rref(z)-E.wcap),E.Rcav-Math.max(z-E.ZA,0)*E.cone);
  E.capCav=z=>{
    const body=(z>=E.ZL&&z<E.ceil)?capBody(z):-1;
    const bore=(z>=E.Z0&&z<=E.ZL+0.5)?E.Rbore:-1;
    return Math.max(body,bore);
  };
  /* OBRYS ZEWNĘTRZNY: kształt wybrany suwakami, ale nigdy cieńszy niż wnętrze + minimalna ścianka (miseczka: wallCup, czapka: 2,6, kołnierz: 2,0).
     Poza zakresem wnęki obrys schodzi do zera ze spadkiem SL, żeby nie było uskoków. Przy domyślnym kształcie obrys = powłoka odniesienia. */
  E.Rshape=sup(P.eggW/2,E.ZM,E.H,P.eggNL,P.eggNU);
  const pieces=[[E.floor,E.ZS,z=>E.cupCav(z)+E.wallCup],[E.Z0,E.ZL+0.5,()=>E.Rbore+2.0],[E.ZL,E.ceil-1e-6,z=>capBody(z)+E.wcap]];
  E.need=z=>{let r=0;for(const[a,b,f]of pieces){const v=z<a?f(a)-SL*(a-z):z>b?f(b)-SL*(z-b):f(z);if(v>r)r=v;}return r;};
  E.R=z=>Math.max(E.Rshape(z),E.need(z));
  E.Hout=Math.max(E.H,E.ceil+(capBody(E.ceil-1e-6)+E.wcap)/SL);
  E.RMAX=0;E.deficit=0;
  for(let z=0;z<=E.Hout;z+=0.25){E.RMAX=Math.max(E.RMAX,E.R(z));E.deficit=Math.max(E.deficit,E.need(z)-E.Rshape(z));}
  const r0=Math.hypot(P.earX,Y0);
  E.P0=side=>{let lo=E.ZM,hi=E.Hout;for(let i=0;i<60;i++){const m=(lo+hi)/2;if(E.R(m)>r0)lo=m;else hi=m;}return[side*P.earX,Y0,(lo+hi)/2];};
  E.sdf=(x,y,z)=>{const R=E.R(z),dR=(E.R(z+0.3)-E.R(z-0.3))/0.6;return(R+E.amp*0.6-Math.sqrt(x*x+y*y))/Math.sqrt(1+dR*dR);};
  return E;
}
function eggGrid(E,zlo,zhi,vox){const h=E.RMAX+3;return mkGrid(-h,h,-h,h,zlo,zhi,vox);}
function leafFlat(L,hw){
  const cv=new Canvas(-6,6,-4.5,L+2,0.1),w=b=>{const u=Math.max(b,0)/L;return u<0.45?2.6+(hw-2.6)*Math.sin(Math.PI*Math.min(u/0.45,1)/2):hw*Math.pow(Math.max(1-Math.pow((u-0.45)/0.55,1.8),0),1/1.8);};
  cv.poly(polyLR(b=>-w(b),w,linsp(-3,L,120)));cv.openR(0.8);
  return new FlatPart(cv,3.0,{w:0.8,k:1.1});
}

/* ======== budowa modeli ======== */
function buildReal(id,P,opt){
  const F=M[id].f,parts=[],warn=[];
  const vox=opt.vox||(opt.draft?1.0:opt.lo?0.6:0.45),ex=opt.explode||0;
  if(F.kind==='ghost')return buildGhost(P,vox,parts,warn);
  if(F.kind==='line')return buildLine(id,P,vox,ex,parts,warn);
  if(F.kind==='egg')return buildEgg(id,P,vox,ex,parts,warn,opt);
  /* figurka na korpusie bazowym */
  const B=bunDef(P),tilt=P.earTilt*D2R,frameFn=side=>mountFrame(side,B.P0(side),tilt);
  const cres=opt.lo||opt.draft?0.2:0.1;let spec=F.ears?earSpec(F.ears,P,cres):null,xh=Math.max(21,B.R+2.5),ylo=-xh,yhi=xh,zhi=B.P0(1)[2]+6;
  if(spec)zhi=Math.max(zhi,B.P0(1)[2]+spec.L*Math.cos(tilt)+6);
  if(F.ears==='ant')xh=Math.max(28,B.P0(1)[0]+spec.ar(1)[1]*Math.cos(tilt)+3);
  if(F.tail){yhi=Math.max(yhi,12+P.tailL*Math.sin(P.tailA*D2R)+P.tailR+3);zhi=Math.max(zhi,14+P.tailL*Math.cos(P.tailA*D2R)+P.tailR+3);}
  if(F.wings){const s=P.wingS,ca=Math.cos(P.wingA*D2R),sa=Math.sin(P.wingA*D2R);xh=Math.max(xh,(19+31*s)*ca+Math.abs(P.wingC)*sa+6);yhi=Math.max(yhi,(19+31*s)*sa+Math.abs(P.wingC)*ca+6);zhi=Math.max(zhi,P.wingZ+71+43*s+4,P.haloZ+P.haloRo+3);}
  if(F.hat)zhi=B.top+4;
  const G=mkGrid(-xh,xh,ylo,yhi,-1,zhi,vox);
  fillBun(G,B);
  const detach=!!P.detach&&spec&&!F.wings;
  if(spec){if(detach)cutSockets(G,frameFn);else fuseEars(G,B,spec,P,frameFn);}
  if(F.tail){const tf=tailF(P,P.ribPow);boxField(G,[-12,12,0,yhi,0,zhi],tf);}
  if(F.eyes){for(const sx of[1,-1])boxField(G,[-(B.HR+3),B.HR+3,-(B.HR+4),0,B.HC-B.HR,B.HC+B.HR],eyeCapF(B,P,sx));
    boxField(G,[-6,6,-(B.HR+P.beakL+2),-(B.HR-6),B.HC-4.2-5,B.HC-4.2+5],beakF(B.HC-4.2,B.HR-0.1,P.beakL,P.beakW,3.0,4.0));}
  if(F.wings){
    boxField(G,[-P.haloRo-1,P.haloRo+1,-P.haloT/2-1,P.haloT/2+1,P.haloZ-24,P.haloZ+P.haloRo+1],haloF(P));
    const w=wingFlat(P,opt.lo||opt.draft?0.2:0.1);
    for(const s of[1,-1])localField(G,wingFrame(P,s),(a,b,c)=>w.fp.F(a,b,c),w.a,w.b,[-1,P.wingT+1.7],'max');
  }
  if(F.hat){
    const amp=B.amp,RCV=B.HR+amp+0.45,E35=Math.atan(1/LINE.const.LP_SLOPE),zt=B.HC+RCV*Math.cos(E35),rt=RCV*Math.sin(E35);
    const zb=B.HC+1.5,Rb=P.hatRb;
    const h=mkHat(F.hat,zb,P.hatTop,Rb,nRibs(Rb),0,P.hatP,P);
    const h2=Math.max(24,Rb+B.amp+3),G2=mkGrid(-h2,h2,-h2,h2,zb-1,P.hatTop+1,vox);
    hatField(G2,h,amp,B.pw,'set');planeZ(G2,zb,P.hatTop);
    cutLathe(G2,z=>{const r=z<zt?Math.sqrt(Math.max(RCV*RCV-(z-B.HC)*(z-B.HC),0)):rt-(z-zt)/Math.tan(E35);return z<zt+Math.tan(E35)*(rt-3)?r:-1;});
    cutSockets(G,frameFn);
    parts.push({name:'korpus',m:meshFromGrid(G),g:'korpus'});
    const hm=meshFromGrid(G2);if(ex)translate(hm,0,ex,0);
    parts.push({name:'czapka',m:hm,g:'czapka'});
    return{parts,warn};
  }
  const sdfs=[B.sdf];
  if(detach){
    parts.push({name:'korpus',m:meshFromGrid(G),g:'korpus'});
    addEarParts(parts,spec,frameFn,sdfs,vox,ex,F.ears==='ant'?'poroże':'ucho');
  }else parts.push({name:'korpus',m:meshFromGrid(G)});
  return{parts,warn};
}

function buildGhost(P,vox,parts,warn){
  const H=P.height,RH=P.hemR,RD=P.headR,ZD=H-RD,K=Math.round(P.scal),HS=P.scalD,N=Math.round(P.ribs),amp=P.ribDepth/2;
  const Rp=z=>{const fl=RD+(RH-RD)*Math.pow(clamp((ZD-z)/ZD,0,1),1.4),dm=Math.sqrt(Math.max(RD*RD-(z-ZD)*(z-ZD),0));return z>=ZD?dm:fl;};
  const h=RH+3.5,G=mkGrid(-h,h,-h,h,-1,H+1.5,vox);
  latheField(G,{R:Rp,N,amp,pow:P.ribPow});
  const{nx,ny,nz,v,F}=G,Rc=new Float32Array(nz);
  for(let k=0;k<nz;k++)Rc[k]=Rp(G.z0+k*v);
  planeZ(G,-1e9,H);
  for(let k=0;k<nz;k++){const z=G.z0+k*v;if(z>HS+2*v)break;for(let j=0;j<ny;j++){const y=G.y0+j*v,o=nx*(j+ny*k);
    for(let i=0;i<nx;i++){const x=G.x0+i*v;let f=F[o+i];if(f<-3)continue;
      const rho=Math.sqrt(x*x+y*y),zh=HS*(1-Math.cos(K*Math.atan2(y,x)))/2*sstep(rho,6,15);
      if(z-zh<f)F[o+i]=z-zh;}}}
  if(P.face){
    const pit=(x,y,z,xc,zc,a,b,D)=>{const s=-y,R=Rc[Math.round((z-G.z0)/v)],ss=Math.sqrt(Math.max(R*R-x*x,0)),q2=((x-xc)/a)*((x-xc)/a)+((z-zc)/b)*((z-zc)/b),q=Math.sqrt(q2),dep=D*Math.max(1-q2,0);
      return Math.min((1-q)*Math.min(a,b),s-(ss-dep));};
    const D=P.pitD,ze=H-16.5,zm=H-34.5;
    boxCut(G,[-14,14,-RH-2,0,zm-8,ze+8],(x,y,z)=>-Math.max(pit(x,y,z,-7.4,ze,3.4,5.5,D),pit(x,y,z,7.4,ze,3.4,5.5,D),pit(x,y,z,0,zm,4.4,5.4,D*1.07)));
  }
  parts.push({name:'duszek',m:meshFromGrid(G)});
  return{parts,warn};
}

function buildEgg(id,P,vox,ex,parts,warn,opt0){
  const E=eggDef(P),F=M[id].f,frameFn=side=>mountFrame(side,E.P0(side),P.earTilt*D2R);
  /* miseczka */
  {const G=eggGrid(E,-1,E.ZS+E.lipH+1.5,vox);
   latheField(G,{R:z=>z<=E.ZS?E.R(z):E.Rlip,N:E.n,amp:E.amp,pow:E.pw,w:z=>z<=E.ZS?1:0});
   cutLathe(G,E.cupCav);planeZ(G,0,E.ZS+E.lipH);
   parts.push({name:'miseczka',m:meshFromGrid(G),g:'miseczka'});}
  /* czapka */
  const kind=F.cap;let ztop=E.Hout+2.5;
  if(kind==='krasnal'||kind==='mikolaj')ztop=P.hatTop+2;
  if(kind==='chick')ztop=101;
  if(kind==='ears')ztop=E.P0(1)[2]+P.earL+4;
  const G=eggGrid(E,E.Z0-1,ztop,vox);
  latheField(G,{R:E.R,N:E.n,amp:E.amp,pow:E.pw});
  if(kind==='krasnal'||kind==='mikolaj'){
    const h=mkHat(kind,P.hatZ,P.hatTop,P.hatRb,nRibs(P.hatRb-1),1.4,P.hatP,P);hatField(G,h,E.amp,E.pw,'max');
  }
  if(kind==='chick'){
    const ze=63,ph=38*D2R,rs=E.R(ze);
    for(const sx of[1,-1]){const phi=-Math.PI/2+sx*ph,cx=(rs+0.2)*Math.cos(phi),cy=(rs+0.2)*Math.sin(phi),r=P.eyeR;
      boxField(G,[cx-r-1,cx+r+1,cy-r-1,cy+r+1,ze-r-1,ze+r+1],(x,y,z)=>{
        const u=(x-cx)*Math.cos(phi)+(y-cy)*Math.sin(phi),v=-(x-cx)*Math.sin(phi)+(y-cy)*Math.cos(phi);
        return(1-Math.sqrt((u/(r))**2+(v/(r*1.125))**2+((z-ze)/(r*1.125))**2))*r;});}
    const zb=56,rb=E.R(zb);boxField(G,[-5,5,-(rb+P.beakL+3),-(rb-6),zb-4,zb+4],beakF(zb,rb+0.6,P.beakL,3.6,3.0,5.0));
    const zt=85.5;
    for(const[g,xo]of[[-26,-1.4],[0,0],[26,1.4]]){
      const gr=g*D2R,B=[Math.sin(gr),0,Math.cos(gr)],C=[0,-1,0],A=[B[1]*C[2]-B[2]*C[1],B[2]*C[0]-B[0]*C[2],B[0]*C[1]-B[1]*C[0]];
      const L=(g===0?P.crestL:P.crestL*0.82),fp=leafFlat(L,3.0);
      localField(G,mkFrame([xo,1.5,zt],A,B,C),(a,b,c)=>Math.min(fp.F(a,b,c),b+4.0),[-6,6],[-5,L+2],[-1,4],'max');}
  }
  if(kind==='ears'){
    const spec=earSpec('rab',P,opt0.lo||opt0.draft?0.2:0.1);fuseEars(G,null,spec,P,frameFn);
  }
  cutLathe(G,E.capCav);planeZ(G,E.Z0,1e9);
  if(kind==='plain')cutSockets(G,frameFn);
  const cm=meshFromGrid(G);if(ex)translate(cm,0,ex,0);
  parts.push({name:'czapka',m:cm,g:'czapka'});
  /* uwagi */
  let wc=1e9;for(let z=E.floor;z<=E.ZL;z+=0.5){const c=E.cupCav(z);if(c>0)wc=Math.min(wc,E.R(z)-c-E.amp);}
  let wp=1e9;for(let z=E.ZL;z<E.ceil;z+=0.5){const c=E.capCav(z);if(c>0)wp=Math.min(wp,E.R(z)-c-E.amp);}
  if(E.deficit>0.02)warn.push('Obrys jest za chudy dla wnętrza o '+E.deficit.toFixed(1).replace('.',',')+' mm: ścianka jest tam pogrubiona do minimum, a wnętrze zostaje bez zmian. Zwiększ szerokość lub wysokość.');
  else if(wc<1.6)warn.push('Ścianka miseczki ma '+Math.max(0,wc).toFixed(1).replace('.',',')+' mm. Zmniejsz wnękę.');
  else if(wp<1.2)warn.push('Ścianka czapki ma '+Math.max(0,wp).toFixed(1).replace('.',',')+' mm. Zmniejsz wnękę.');
  if(E.ceil>E.H-1.6)warn.push('Sufit wnęki jest za blisko czubka jajka.');
  return{parts,warn};
}

/* ===== STANDARD: modele z profilu linii (dynia, bałwan). Profil, pasma żeber i porty pochodzą z line.json (Python = źródło prawdy) ===== */
function lineTab(id){
  const t=LINE.models[id].R,n=t.length,zs=new Float64Array(n),rs=new Float64Array(n);
  for(let i=0;i<n;i++){zs[i]=t[i][0];rs[i]=t[i][1];}
  return z=>{
    if(z<=zs[0])return rs[0];if(z>=zs[n-1])return rs[n-1];
    let lo=0,hi=n-1;while(hi-lo>1){const m=(lo+hi)>>1;if(zs[m]<=z)lo=m;else hi=m;}
    const d=zs[hi]-zs[lo];return d<1e-9?rs[hi]:rs[lo]+(rs[hi]-rs[lo])*(z-zs[lo])/d;
  };
}
/* bryła obrotowa z pasmami żeber: F = R + amp*fade(R)*sum(w_i*rib_i(N_i th)) - rho, ograniczona płaszczyznami zlo / zhi (i opcjonalnie o.top(rho)) */
function latheBands(G,o){
  const{nx,ny,nz,v,F}=G,nc=nx*ny,bs=o.bands,fd=o.fade,{rho}=colInfo(G,0,1),ribs=bs.map(b=>colInfo(G,b.N,o.pow).rib),W=new Float64Array(bs.length);
  for(let k=0;k<nz;k++){
    const z=G.z0+k*v;if(z<o.zlo-2*v||z>o.zhi+2*v)continue;
    const R=o.R(z),pl=Math.min(z-o.zlo,o.zhi-z),a=o.amp*clamp((R-fd[0])/(fd[1]-fd[0]),0,1),off=k*nc,b=R-1e-3;
    let any=false;
    for(let i=0;i<bs.length;i++){const q=bs[i];let w=1;if(q.up)w*=sstep(z,q.up[0],q.up[1]);if(q.down)w*=1-sstep(z,q.down[0],q.down[1]);W[i]=a*w;if(W[i]!==0)any=true;}
    for(let c=0;c<nc;c++){
      let m=0;if(any)for(let i=0;i<bs.length;i++)if(W[i]!==0)m+=W[i]*ribs[i][c];
      let val=b+m-rho[c];if(val>pl)val=pl;
      if(o.top){const t=o.top(rho[c])-z;if(t<val)val=t;}
      F[off+c]=val;
    }
  }
}
/* szerokość domyślna = średnica po grzbietach żeber (2 * promień profilu + głębokość rowków z linii) */
function lineW0(id){let m=0;for(const p of LINE.models[id].R)if(p[1]>m)m=p[1];return 2*m+2*LINE.models[id].ribs.amp;}
/* skala: albo jedna (P.scale, bałwan), albo osobno szerokość (sw, z P.width) i wysokość (sh, z P.height) (dynia); N żeber rośnie z szerokością, rozstaw zostaje */
function lineSpec(id,P){
  const L=LINE.models[id],R0=lineTab(id);
  let rmax0=0;for(const p of L.R)if(p[1]>rmax0)rmax0=p[1];
  const sw=P.width!=null?(P.width-P.ribDepth)/(2*rmax0):P.scale,sh=P.height!=null?P.height/L.H:P.scale,sc=a=>a&&a.map(x=>x*sh);
  const ports={};
  for(const k in L.ports){const f=L.ports[k].frame;ports[k]={O:[f.O[0]*sw,f.O[1]*sw,f.O[2]*sh],A:f.A,B:f.B,C:f.C};}
  const S={L,s:sw,sw,sh,H:L.H*sh,rmax:rmax0*sw,R:z=>sw*R0(z/sh),ports,
    bands:L.ribs.bands.map(b=>({N:Math.max(1,Math.round(b.N*sw)),up:sc(b.up),down:sc(b.down)})),fade:L.ribs.fade,top:null};
  if(L.top){const T=L.top,rs=T.R_SH*sw;S.top=rho=>{const q=Math.min(rho/rs,1);return sh*T.H_TOP-sh*T.DIP*Math.pow(1-q*q,1.5);};}
  /* przybliżona odległość do koperty korpusu (do przycinania dodatków): promień + ENV_PAD / normalna, a nad dnem zagłębienia wysokość */
  S.sdf=(x,y,z)=>{const R=S.R(z),dR=(S.R(z+0.3)-S.R(z-0.3))/0.6;let d=(R+LINE.const.ENV_PAD*0.6-Math.sqrt(x*x+y*y))/Math.sqrt(1+dR*dR);
    if(S.top)d=Math.min(d,S.top(Math.sqrt(x*x+y*y))+LINE.const.PAD_MIN-z);return d;};
  return S;
}
function lineGrid(id,P,vox){
  const S=lineSpec(id,P),h=S.rmax+P.ribDepth/2+3,G=mkGrid(-h,h,-h,h,-1,S.H+1.5,vox);
  latheBands(G,{R:S.R,bands:S.bands,amp:P.ribDepth/2,pow:P.ribPow,fade:S.fade,zlo:0,zhi:S.H,top:S.top});
  for(const k in S.ports)localField(G,S.ports[k],socketF,[-5,5],[-9,2],[-1,6],'cut');
  return{G,S};
}
/* dodatek lokalny (ogonek, nos): siatka w ramce portu; ex = wersja do druku (płaska strona c=0 na stole), g = w modelu */
function linePart(name,S,port,fn,ar,br,cr,vox,ex,flip){
  const fr=S.ports[port],v=clamp(vox*0.6,0.22,0.45),G=mkGrid(ar[0],ar[1],br[0],br[1],cr[0],cr[1],v);
  localField(G,IDM,fn,ar,br,cr,'max');
  const m=surfaceNets(G),exm={p:m.p.slice(),i:m.i.slice()};
  if(flip)xf(exm,(a,b,c)=>[a,c,-b]);toPage(exm);                     /* ogonek: do druku końcem na stole (jak w skrypcie) */
  const g=frameXf(fr,{p:m.p,i:m.i});toPage(g);
  if(ex){const B=fr.B,k=ex*0.5;translate(g,B[0]*k,B[2]*k,-B[1]*k);}
  return{name,m:g,ex:exm,g:name};
}
function buildLine(id,P,vox,ex,parts,warn){
  const{G,S}=lineGrid(id,P,vox);
  parts.push({name:'korpus',m:meshFromGrid(G),g:'korpus'});
  if(id==='dynia'){
    const T=LINE.models.dynia.stem;
    const fn=(a,b,c)=>{
      const t=clamp(b/T.H,0,1),xc=T.bend*t*t,r=T.RT+(T.R0-T.RT)*Math.pow(1-t,3),y=2.5-c,dx=a-xc,rho=Math.hypot(dx,y);
      const q=Math.cos(T.N*Math.atan2(y,dx));
      let f=Math.min(r+T.amp*sgnPow(q,0.8)-1e-3-rho,T.H-b,b+3.0);
      const fr=S.ports.stem,X=fr.O[0]+a*fr.A[0]+b*fr.B[0]+c*fr.C[0],Y=fr.O[1]+a*fr.A[1]+b*fr.B[1]+c*fr.C[1],Z=fr.O[2]+a*fr.A[2]+b*fr.B[2]+c*fr.C[2];
      f=Math.min(f,-(S.sdf(X,Y,Z)+GAP));
      return Math.max(f,rboxF(a,b,c,[-PEG_W/2,-PEG_L,0],[PEG_W/2,1,PEG_W],PEG_R));
    };
    const p=linePart('ogonek',S,'stem',fn,[-12,12],[-9,T.H+1],[-9,14],vox,ex,true);parts.push(p);
  }else{
    const n=LINE.models.balwan.nose;
    const fn=(a,b,c)=>{
      const r=n.RT+(n.R0-n.RT)*clamp(1-b/n.L,0,1),cc=0.7*r;
      let f=Math.min(r-Math.hypot(a,c-cc),n.L-b,c,b+3.0);
      const fr=S.ports.nose,X=fr.O[0]+a*fr.A[0]+b*fr.B[0]+c*fr.C[0],Y=fr.O[1]+a*fr.A[1]+b*fr.B[1]+c*fr.C[1],Z=fr.O[2]+a*fr.A[2]+b*fr.B[2]+c*fr.C[2];
      f=Math.min(f,-(S.sdf(X,Y,Z)+GAP));
      return Math.max(f,rboxF(a,b,c,[-PEG_W/2,-PEG_L,0],[PEG_W/2,1,PEG_W],PEG_R));
    };
    parts.push(linePart('nos',S,'nose',fn,[-6,6],[-9,n.L+1],[-1,10],vox,ex,false));
  }
  return{parts,warn};
}

/* ===== definicje modeli ===== */
