function finalize(parts){
  let x0=1e9,x1=-1e9,y0=1e9,y1=-1e9,z0=1e9,z1=-1e9;
  for(const q of parts){const p=q.m.p;for(let k=0;k<p.length;k+=3){const x=p[k],y=p[k+1],z=p[k+2];
    if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y;if(z<z0)z0=z;if(z>z1)z1=z;}}
  const cx=(x0+x1)/2,cz=(z0+z1)/2;
  for(const q of parts)translate(q.m,-cx,-y0,-cz);
  return{w:x1-x0,h:y1-y0,d:z1-z0};
}
function triCount(parts){let n=0;for(const q of parts)n+=q.m.i.length/3;return n;}
function exportGroups(res){
  const gs=new Map();
  for(const q of res.parts){const g=q.g||'';if(!gs.has(g))gs.set(g,[]);gs.get(g).push({name:q.name,m:cloneM(q.ex||q.m)});}
  const out=[];for(const[g,ps]of gs){finalize(ps);out.push({g,parts:ps});}return out;
}
function stlBytes(parts){
  const n=triCount(parts),buf=new ArrayBuffer(84+50*n),dv=new DataView(buf);
  const hdr='Zebrowana kolekcja';for(let k=0;k<hdr.length;k++)dv.setUint8(k,hdr.charCodeAt(k)&127);
  dv.setUint32(80,n,true);let o=84;
  const T=(p,v)=>[p[v*3],-p[v*3+2],p[v*3+1]];
  for(const q of parts){const p=q.m.p,ix=q.m.i;
    for(let k=0;k<ix.length;k+=3){
      const a=T(p,ix[k]),b=T(p,ix[k+1]),c=T(p,ix[k+2]);
      const ux=b[0]-a[0],uy=b[1]-a[1],uz=b[2]-a[2],vx=c[0]-a[0],vy=c[1]-a[1],vz=c[2]-a[2];
      let nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx;const l=Math.hypot(nx,ny,nz)||1;nx/=l;ny/=l;nz/=l;
      for(const f of[nx,ny,nz,...a,...b,...c]){dv.setFloat32(o,f,true);o+=4;}
      dv.setUint16(o,0,true);o+=2;
    }}
  return new Uint8Array(buf);
}
/* nazwy plików (bez budowania siatek) */
function fileNames(id,P){
  const F=M[id].f;
  if(F.kind==='line')return M[id].files.map(s=>id+'_'+s+'.stl');
  if(F.kind==='egg'&&F.real)return[id+'_miseczka.stl',id+'_czapka.stl'];
  if(F.hat)return[id+'_korpus.stl',id+'_czapka.stl'];
  if(P&&P.detach&&F.ears)return[id+'_korpus.stl',id+'_ucho_prawe.stl',id+'_ucho_lewe.stl'];
  return[id+'.stl'];
}

